export const TaskAssignmentStatusKeyToLabel = {
  'ToDo': 'To do',
  'InProgress': 'In progress',
  'Completed': 'Completed'
} as const;
export type TaskAssignmentStatusKey = keyof typeof TaskAssignmentStatusKeyToLabel;

export interface TaskAssignment {
  /**
   * @displayName Task Assignment ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Title
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  title: string;
  /**
   * @displayName Assigned User Display Name
   * @validationRule Required for create/update operations
   */
  assignedUserDisplayName: string;
  /**
   * @displayName Assigned User Email or UPN
   * @validationRule Required for create/update operations
   */
  assignedUserEmailOrUPN: string;
  /**
   * @displayName Assigned User Job Title
   */
  assignedUserJobTitle?: string;
  /**
   * @displayName Assigned User Object ID
   * @validationRule Required for create/update operations
   */
  assignedUserObjectID: string;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName Due Date
   * @validationRule Required for create/update operations
   */
  dueDate: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: TaskAssignmentStatusKey;
}

export const _TaskAssignment = 'TaskAssignment' as const;